// Step 8 fixtures: fake Calendly events relative to now, sent in order to PF Calendly Capture.
//   T7   K: created, then canceled before the check  -> never asked
//   T8   R: created, then rescheduled to R2          -> R never asked, R2 asked
//   T11  H: host is not on the allowlist             -> guard_blocked, no DM
//   T5c  N: normal session, host answers No, then ignores the rebook question
const run = $now.toFormat('HHmmss');
const RR = 'https://api.calendly.com/event_types/ebd64db8-7c09-4e31-bc2e-339065fbb930';
const inv = (c) => `https://api.calendly.com/scheduled_events/MOCK-EVT-${c}-${run}/invitees/MOCK-INV-${c}-${run}`;
const evt = (c) => `https://api.calendly.com/scheduled_events/MOCK-EVT-${c}-${run}`;
const start = $now.minus({ minutes: 2 }).startOf('second');
const end = start.plus({ minutes: 5 });
const host = { user: 'https://api.calendly.com/users/MOCK-HOST', user_email: 'aniol.moner@n8n.io', user_name: 'Aniol Moner' };
const otherHost = { user: 'https://api.calendly.com/users/MOCK-OTHER', user_email: 'other.host@example.com', user_name: 'Other Host' };

function payload(c, first, tag, o = {}) {
  return {
    uri: inv(c), email: `aniol.moner+${tag}@n8n.io`, name: `${first} Mock`, first_name: first, last_name: 'Mock',
    status: o.cancel ? 'canceled' : 'active', timezone: 'Europe/Madrid',
    rescheduled: o.rescheduled ?? false, old_invitee: o.old ?? null, new_invitee: o.new ?? null,
    reschedule_url: `https://calendly.com/reschedulings/MOCK-${c}`, cancel_url: `https://calendly.com/cancellations/MOCK-${c}`,
    cancellation: o.cancel ? { canceled_by: `${first} Mock`, canceler_type: 'invitee', reason: o.cancel, created_at: $now.toISO() } : null,
    no_show: null, tracking: {},
    scheduled_event: {
      uri: evt(c), name: 'Research with n8n', event_type: RR,
      start_time: start.toUTC().toISO(), end_time: end.toUTC().toISO(), status: o.cancel ? 'canceled' : 'active',
      event_memberships: [o.host ?? host],
    },
  };
}
const created = (p, label) => ({ json: { _label: label, event: 'invitee.created', payload: p } });
const canceled = (p, label) => ({ json: { _label: label, event: 'invitee.canceled', payload: p } });

return [
  created(payload('K', 'Kim', 't7'), 'T7 create'),
  canceled(payload('K', 'Kim', 't7', { cancel: 'Something came up' }), 'T7 cancel'),
  created(payload('R', 'Rui', 't8'), 'T8 original'),
  canceled(payload('R', 'Rui', 't8', { cancel: 'Rescheduled', rescheduled: true, new: inv('R2') }), 'T8 old canceled as rescheduled'),
  created(payload('R2', 'Rui', 't8', { old: inv('R') }), 'T8 new booking'),
  created(payload('H', 'Hana', 't11', { host: otherHost }), 'T11 other host'),
  created(payload('N', 'Nora', 't5c'), 'T5c no rebook answer'),
];
